create table users(id uuid primary key default gen_random_uuid(),role text not null check(role in('admin','medico','fisio','recepcao','paciente')),name text not null,email text unique not null,phone text,pw_hash text not null,active boolean not null default true,lang text not null default 'pt',ai_consent boolean not null default false,created_at timestamptz not null default now());
create table care_team(patient_id uuid references users(id),professional_id uuid references users(id),primary key(patient_id,professional_id));
create table channels(id uuid primary key default gen_random_uuid(),name text unique not null);
create table messages(id uuid primary key default gen_random_uuid(),room text not null,sender_id uuid not null references users(id),body_enc text not null,lang text,pinned boolean not null default false,urgent boolean not null default false,created_at timestamptz not null default now());
create index on messages(room,created_at desc);
create table packages(id uuid primary key default gen_random_uuid(),patient_id uuid not null references users(id),name text not null,total_sessions int not null check(total_sessions>0),used_sessions int not null default 0,price_cents int not null,created_at timestamptz not null default now(),check(used_sessions<=total_sessions));
create table appointments(id uuid primary key default gen_random_uuid(),patient_id uuid not null references users(id),professional_id uuid not null references users(id),starts_at timestamptz not null,ends_at timestamptz not null,status text not null default 'agendado' check(status in('agendado','confirmado','na_recepcao','em_atendimento','finalizado','faltou','cancelado')),package_id uuid references packages(id),noshow_risk numeric(3,2),reminded_at timestamptz,created_at timestamptz not null default now());
create index on appointments(starts_at);
create table payments(id uuid primary key default gen_random_uuid(),kind text not null check(kind in('entrada','saida')),amount_cents int not null check(amount_cents>0),category text,method text,note text,patient_id uuid references users(id),package_id uuid references packages(id),paid_at timestamptz not null default now());
create table transcripts(id uuid primary key default gen_random_uuid(),appointment_id uuid not null references appointments(id),speaker_id uuid not null references users(id),lang text,text_enc text not null,translated_enc text,to_lang text,created_at timestamptz not null default now());
create table clinical_entries(id uuid primary key default gen_random_uuid(),patient_id uuid not null references users(id),author_id uuid not null references users(id),kind text not null,source text not null,content_enc text not null,approved boolean not null default false,approved_by uuid references users(id),created_at timestamptz not null default now());
create table exercises(id uuid primary key default gen_random_uuid(),title text not null,description text,steps jsonb not null default '[]',video_url text,created_by uuid references users(id));
create table assignments(id uuid primary key default gen_random_uuid(),patient_id uuid not null references users(id),exercise_id uuid not null references exercises(id),professional_id uuid not null references users(id),freq_per_week int not null,sets int not null,reps int not null,start_date date not null,end_date date not null,goal text,active boolean not null default true);
create table task_logs(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references assignments(id),done_at timestamptz not null default now(),pain int check(pain between 0 and 10),note text);
create table goals(id uuid primary key default gen_random_uuid(),patient_id uuid not null references users(id),description text not null,target int not null check(target between 0 and 10),due date not null,active boolean not null default true);
create table evolution(id uuid primary key default gen_random_uuid(),patient_id uuid not null references users(id),at timestamptz not null default now(),eva int not null check(eva between 0 and 10),note text,source text not null default 'profissional');
create table documents(id uuid primary key default gen_random_uuid(),patient_id uuid not null references users(id),author_id uuid not null references users(id),kind text not null,texto text not null,hash text not null,seal text not null,created_at timestamptz not null);
create table alerts(id uuid primary key default gen_random_uuid(),kind text not null,severity text not null,patient_id uuid references users(id),user_id uuid references users(id),detail json,ack boolean not null default false,created_at timestamptz not null default now());
create table audit_log(id bigserial primary key,at timestamptz not null,user_id uuid,action text not null,entity text not null,entity_id text,ip text,meta json,prev_hash text not null,hash text not null);
create function audit_no_mutation() returns trigger as $$ begin raise exception 'audit_log é imutável'; end $$ language plpgsql;
create trigger audit_row before update or delete on audit_log for each row execute function audit_no_mutation();
create trigger audit_trunc before truncate on audit_log for each statement execute function audit_no_mutation();
